// TEMP read-only, counts only, no PII: morning check for Nov 12.
import { sql } from "~/db";
import { BOT_EXCLUSION_SQL } from "~/lib/bot-exclusion";
const s = sql();
const bot = s.unsafe(BOT_EXCLUSION_SQL);
const out = async (label: string, p: Promise<unknown>) => { try { console.log("AM", label, JSON.stringify(await p)); } catch (e) { console.log("AM", label, "ERR", (e as Error).message.slice(0, 160)); } };
await out("visitors by ET day and source", s`SELECT (created_at AT TIME ZONE 'America/New_York')::date AS day, COALESCE(NULLIF(source,''),'direct') AS source, COALESCE(NULLIF(medium,''),'none') AS medium, COUNT(DISTINCT visitor_id)::int AS v FROM page_views WHERE created_at > now() - interval '2 days' AND NOT ${bot} GROUP BY 1, 2, 3 ORDER BY 1, 4 DESC`);
await out("key events by ET day", s`SELECT (created_at AT TIME ZONE 'America/New_York')::date AS day, event_name, COUNT(DISTINCT visitor_id)::int AS v, COUNT(*)::int AS n FROM funnel_events WHERE created_at > now() - interval '2 days' AND NOT ${bot} AND (event_name LIKE 'company_%' OR event_name LIKE '%_click' OR event_name IN ('radar_scan_start','radar_scan_complete','radar_bids_first_shown','checkout_session_created','purchase_completed','radar_lead_captured','bid_lock_sheet_shown')) GROUP BY 1, 2 ORDER BY 1, 3 DESC`);
await out("company pages viewed (path prefix)", s`SELECT (created_at AT TIME ZONE 'America/New_York')::date AS day, COUNT(DISTINCT visitor_id)::int AS v, COUNT(*)::int AS views FROM page_views WHERE created_at > now() - interval '2 days' AND path LIKE '/company%' AND NOT ${bot} GROUP BY 1 ORDER BY 1`);
await out("company pages, all agents incl crawlers", s`SELECT CASE WHEN LOWER(COALESCE(user_agent,'')) LIKE '%bingbot%' THEN 'bingbot' WHEN LOWER(COALESCE(user_agent,'')) LIKE '%googlebot%' THEN 'googlebot' WHEN LOWER(COALESCE(user_agent,'')) LIKE '%gptbot%' OR LOWER(COALESCE(user_agent,'')) LIKE '%oai-searchbot%' OR LOWER(COALESCE(user_agent,'')) LIKE '%chatgpt%' THEN 'openai' ELSE 'other' END AS agent, COUNT(*)::int AS views FROM page_views WHERE created_at > now() - interval '1 day' AND path LIKE '/company/%' GROUP BY 1 ORDER BY 2 DESC`);
await out("casa clicks by label since Nov 9", s`SELECT COALESCE(label,'') AS label, COUNT(*)::int AS n, COUNT(DISTINCT visitor_id)::int AS v FROM funnel_events WHERE event_name = 'tampa_housing_referral_click' AND created_at >= '2026-11-09' AND NOT ${bot} GROUP BY 1 ORDER BY 2 DESC`);
await out("scans started vs completed by state, 2 days", s`SELECT COALESCE(label,'') AS label, event_name, COUNT(*)::int AS n FROM funnel_events WHERE created_at > now() - interval '2 days' AND NOT ${bot} AND event_name IN ('radar_scan_start','radar_scan_complete','radar_scan_timeout','radar_scan_error') GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 20`);
await out("paid accounts", s`SELECT plan_tier, subscription_status, COUNT(*)::int FROM users WHERE plan_tier IN ('starter','professional') AND subscription_status IS NOT NULL GROUP BY 1, 2`);
process.exit(0);
